import React,{useState} from 'react';
import {assertHourlyPathModel} from '../domain/hourly-path-model.mjs';
import {assertHourlyModelComponents} from '../domain/hourly-model-components.mjs';
import {hourlyModelOverview,hourlyModelSourceConfig} from './hourly-model-view.mjs';

export function HourlyPathControls({data,expanded}){
 const [error,setError]=useState(''),model=data.node.config.model,summary=hourlyModelOverview(data.node.config),surge=data.node.config.family==='SURGE_PATH_FOREST',interval=surge?'1분봉':'1시간봉';
 async function load(event){const file=event.target.files?.[0];if(!file)return;try{if(file.size>180000)throw new Error('180KB 이내의 모델을 선택하세요.');const model=JSON.parse(await file.text());assertHourlyPathModel(model);if(model.timeframe!==(surge?'1m':'1h'))throw Error('입력 주기가 다른 모델입니다.');if(data.node.config.components)assertHourlyModelComponents(data.node.config.components,model);data.onPatch(data.node,{config:{...data.node.config,model}});setError('');}catch(e){setError('모델 형식과 학습 구간을 확인하세요. '+e.message);}finally{event.target.value='';}}
 if(!expanded)return <span className="strategy-inline-caption">{model?interval+' · '+model.horizonBars+'봉 가격 예측':'학습된 버전을 선택하세요'}</span>;
 const policy=data.node.config.policy;
 return <section className="strategy-hourly-model" aria-label={surge?"분봉 급등 학습 판단":"시간봉 가격 예측"}>
  <section className="strategy-model-source" aria-label="모델 라이브러리"><h4>학습된 버전 선택</h4><p>저장된 마인드의 모델을 복사해 이 부품에서 사용합니다.</p>{data.modelSourcesLoading?<p role="status">학습 버전 조회 중…</p>:<label className="field">모델 버전<select aria-label="저장된 학습 모델" disabled={data.saving} value="" onChange={e=>{const source=data.modelSources?.find(v=>v.id===e.target.value);if(source)data.onPatch(data.node,{config:hourlyModelSourceConfig(data.node.config,source)});}}><option value="">학습된 버전 선택</option>{(data.modelSources??[]).filter(v=>v.model.timeframe===(surge?'1m':'1h')).map(v=><option key={v.id} value={v.id}>{v.sources.join(' · ')} · {v.model.training.sampleCount.toLocaleString()}개 표본 · {new Date(v.model.training.lastLabelAt).toLocaleDateString('ko-KR')}</option>)}</select></label>}{!data.modelSourcesLoading&&!data.modelSources?.length&&<p>저장된 학습 버전이 아직 없습니다. 아래에서 모델 파일을 가져올 수 있습니다.</p>}{data.onLoadModels&&<button type="button" className="button small" disabled={data.modelSourcesLoading} onClick={data.onLoadModels}>버전 새로고침</button>}{data.modelSourceError&&<p role="alert">{data.modelSourceError}</p>}</section>
  {summary&&<><dl className="strategy-node-summary"><div><dt>입력</dt><dd>확정 {interval} 30개</dd></div><div><dt>예측 내부</dt><dd>{summary.features}개 특징 · {summary.trees}개 조건나무</dd></div><div><dt>수익률 집계</dt><dd>{summary.geometric?'기하평균 · 로그 학습':'산술 평균'}</dd></div><div><dt>학습 표본</dt><dd>{summary.samples.toLocaleString()}개</dd></div><div><dt>학습 종료</dt><dd><time dateTime={summary.lastLabelAt}>{new Date(summary.lastLabelAt).toLocaleString('ko-KR')}</time></dd></div></dl><button type="button" className="button primary" disabled={data.saving&&!data.readOnly} onClick={()=>data.onOpenModel?.(data.node)}>내부 구성 열기</button></>}
  <p>{surge?'매분 전체 종목의 가격 움직임을 비교하고, 선택한 후보의 학습 예측을 거래비용·현금·보유 가치와 비교합니다.':policy?'6시간 가격 예측을 현금·보유·다른 종목의 비용 차감 가치와 비교하고, 다음 첫 분봉에서 진입가격을 다시 평가합니다.':'출력은 6시간 예상 수익률입니다. 0.1은 10%이며, 연결한 조건·결정 부품에서 매매에 사용합니다.'}</p>
  {policy&&<details><summary>{surge?'후보 탐색·판단 설정':'종목 선택·진입 재평가 설정'}</summary>{Object.entries(surge?{candidateCount:'분봉 분석 종목 수',watchMinutes:'전 종목 비교 구간 · 분',decisionEveryMinutes:'판단 간격 · 분',forecastExitSlippageBps:'예상 청산 슬리피지 · bps'}:{forecastExitSlippageBps:'예상 청산 슬리피지 · bps',entrySlippageBps:'재평가 진입 슬리피지 · bps',readyDelayMs:'시간봉 종료 후 진입 준비 · ms'}).map(([key,title])=><label className="field" key={key}>{title}<input aria-label={title} type="number" min={['candidateCount','watchMinutes','decisionEveryMinutes'].includes(key)?'1':'0'} max={key==='candidateCount'?'40':key==='watchMinutes'?'60':key==='decisionEveryMinutes'?'180':undefined} step={key==='readyDelayMs'||['candidateCount','watchMinutes','decisionEveryMinutes'].includes(key)?'1':'0.1'} value={policy[key]} disabled={data.saving} onChange={e=>data.onPatch(data.node,{config:{...data.node.config,policy:{...policy,[key]:Number(e.target.value)}}})}/></label>)}</details>}
  <details><summary>파일로 모델 가져오기</summary><label className="field">학습 모델 JSON<input type="file" accept=".json,application/json" aria-label="시간봉 학습 모델 파일" disabled={data.saving} onChange={load}/></label></details>{error&&<p role="alert">{error}</p>}
 </section>;
}
